// Classic "starburst seal" verified badge — 16-point burst with a
// white check in the middle, the same shape Instagram and X use.
// Distinct from the rounded BadgeCheck in lucide; built as an inline
// SVG so the spike count + check thickness are tweakable in one
// place without pulling in another icon set.

function VerifiedSeal({ className }: { className?: string }) {
  return (
    <svg
      viewBox="0 0 64 64"
      className={className}
      aria-hidden
      role="img"
    >
      <defs>
        <linearGradient id="vendora-verified-grad" x1="0" y1="0" x2="1" y2="1">
          <stop offset="0%" stopColor="#3aa6ff" />
          <stop offset="100%" stopColor="#1d6dde" />
        </linearGradient>
      </defs>
      {/* 16-point starburst. Outer points at r=30 from center, inner
          notches at r=26. Generated by hand so the rotation lines up
          with Instagram's seal. */}
      <path
        d="M32 2 L36 6.5 L42 4.5 L44 10 L50 10 L50 16 L55.5 18 L53.5 24 L58 28 L54 32 L58 36 L53.5 40 L55.5 46 L50 48 L50 54 L44 54 L42 59.5 L36 57.5 L32 62 L28 57.5 L22 59.5 L20 54 L14 54 L14 48 L8.5 46 L10.5 40 L6 36 L10 32 L6 28 L10.5 24 L8.5 18 L14 16 L14 10 L20 10 L22 4.5 L28 6.5 Z"
        fill="url(#vendora-verified-grad)"
      />
      {/* Check mark. Thick stroke, rounded caps. */}
      <path
        d="M21 33 L29 41 L44 24"
        fill="none"
        stroke="#ffffff"
        strokeWidth="5"
        strokeLinecap="round"
        strokeLinejoin="round"
      />
    </svg>
  );
}

// Blue verified seal next to a vendor's name when they're on the
// Studio tier. Subscription-tier verification — distinct from the
// document-verification badges (ID / insurance / business license)
// in VerificationBadges.tsx. Renders compact by default; pass a
// larger size where the surface is the vendor's hero profile.
export function StudioVerifiedBadge({
  size = "default",
  showLabel = false,
}: {
  size?: "default" | "lg";
  showLabel?: boolean;
}) {
  const iconClass = size === "lg" ? "w-5 h-5" : "w-4 h-4";

  if (showLabel) {
    return (
      <span
        className="inline-flex items-center gap-1.5 rounded-full px-2.5 py-1 text-xs font-semibold"
        title="Verified Studio vendor"
        style={{
          background:
            "linear-gradient(135deg, rgba(56,134,255,0.18) 0%, rgba(56,134,255,0.08) 100%)",
          color: "#1d6dde",
          border: "1px solid rgba(56,134,255,0.35)",
        }}
      >
        <VerifiedSeal className={iconClass} />
        Verified
      </span>
    );
  }

  return (
    <span
      title="Verified Studio vendor"
      className="inline-flex items-center justify-center"
      aria-label="Verified"
    >
      <VerifiedSeal className={iconClass} />
    </span>
  );
}
